26	          setToken(null);
27	        })
28	        .finally(() => setIsLoading(false));
29	    } else {
30	      setIsLoading(false);
31	    }
32	  }, [token]);
33	
34	  const login = async (data: LoginRequest) => {
35	    const response = await authApi.login(data);
36	    const tokenData: TokenResponse = response.data;
